// Helper function to count occurrences of x in the nested list
function CountOccurrences(lst: seq<seq<int>>, x: int): int
    reads lst
    decreases |lst|
    {
        if |lst| == 0 then
            return 0
        else
            return CountOccurrences(lst[1..], x) + CountInRow(lst[0], x)
    }

// Helper function to count occurrences of x in a single row
function CountInRow(row: seq<int>, x: int): int
    reads row
    decreases |row|
    {
        if |row| == 0 then
            return 0
        else
            return (if row[0] == x then 1 else 0) + CountInRow(row[1..], x)
    }

// Helper function to check if the result is sorted by row
function SortedByRow(result: seq<(int, int)>): bool
    reads result
    {
        forall i, j :: 0 <= i < j < |result| ==> result[i].0 <= result[j].0
    }

// Helper function to check if the result is sorted by column descending within the same row
function SortedByColumnDescending(result: seq<(int, int)>): bool
    reads result
    {
        forall i, j :: 0 <= i < j < |result| && result[i].0 == result[j].0 ==> result[i].1 >= result[j].1
    }
